<template>
  <div class="mobile-image-result">
    <!-- 顶部导航栏 -->
    <div class="navbar">
      <div class="nav-title">{{ t('textToImage') }}</div>
    </div>

    <!-- 加载状态 -->
    <div class="loading-container">
      <div class="loading-content" v-if="currentState === 'loading'">
        <div class="loading-icon">
          <lottie-vue path="/static/thinking.json" :loop="true" :autoplay="true" width="80px" height="80px" />
        </div>
        <div class="loading-text">{{ t('generating') }}</div>
      </div>

      <div class="loading-content" v-else-if="currentState === 'success'">
        <div class="image-display">
          <mobile-l-img :src="imageData.url" :preview-list="[imageData.url]" :enable-preview="true" class="result-image"
            w="100%" h="100%" fit="cover" />
        </div>
      </div>

      <div class="loading-content" v-else-if="currentState === 'error'">
        <div class="error-content">
          <div class="error-message">{{ errorMessage }}</div>
          <button class="retry-btn" @click="handleRetry">{{ t('retry') }}</button>
        </div>
      </div>
    </div>

    <!-- 图片信息 -->
    <div v-if="currentState === 'success'" class="image-info">
      <div class="image-info-item">
        <span class="image-info-label">{{ t('seed') }}: {{ seedDisplayValue }}</span>
      </div>
      <!-- 添加喜欢 -->
      <div class="favorite-action" @click="toggleFavorite">
        <mobile-l-img :src="favoriteIcon" w="12px" h="12px" />
        <span class="favorite-text">{{ t('addToFavorites') }}</span>
      </div>
    </div>

         <!-- 按钮组 -->
     <div v-if="currentState === 'success'" class="button-group">
       <div v-for="button in buttonConfigs" :key="button.key" :data-action="button.key" class="action-btn"
         :class="button.className" @click="handleButtonClick(button.key)">
         <mobile-l-img :src="button.icon" w="16px" h="16px" />
         <span>{{ button.text }}</span>
       </div>
       <!-- 占位元素，使总数为双数 -->
       <div v-if="buttonConfigs.length % 2 !== 0" class="action-btn placeholder-btn">
       </div>
     </div>



  </div>
</template>

<script setup>
// 1. 引入区域
import { ref, computed, onMounted, onBeforeUnmount, onUnmounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { showMessageError, showMessageWarning } from '@/utils/mobile-ui-feedback';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import LottieVue from '@/components/lottie.vue';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import { ApiGeneration } from '@/api/api-generation';
import { IMAGE_OPERATIONS } from '@/types/media-tool';
import { ROUTER_PATHS } from '@/router/constants';
import { routerTo } from '@/router/navigation';
import { TaskType, MediaTaskPolling } from '@/presenter/media-task-polling';
import { debounce, downloadImage } from '@/utils/util.js';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { handleMobileMediaAction } from '@/utils/dialogMethod/mobile-media-action-handler.js';

// 2. 变量区域
const route = useRoute();
const router = useRouter();
const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 响应式变量
const currentState = ref('loading'); // 'loading' | 'success' | 'error'
const currentTaskId = ref('');
const imageData = ref({
  url: '',
  seed: '',
  media_id: ''
});
const isFavorited = ref(false);
const errorMessage = ref('');

// 按钮配置数组
const buttonConfigs = ref([
  {
    key: IMAGE_OPERATIONS.DOWNLOAD,
    icon: '/static/images/download_icon.png',
    text: computed(() => t('download')),
    className: 'download-btn'
  },
  {
    key: IMAGE_OPERATIONS.EDIT,
    icon: '/static/images/edit_icon.png',
    text: computed(() => t('edit')),
    className: 'edit-btn'
  },
  {
    key: IMAGE_OPERATIONS.ENHANCE,
    icon: '/static/images/enhance_icon.png',
    text: computed(() => t('enhance')),
    className: 'enhance-btn'
  },
  {
    key: IMAGE_OPERATIONS.TO_VIDEO,
    icon: '/static/images/video_icon.png',
    text: computed(() => t('toVideo')),
    className: 'video-btn'
  },
  {
    key: IMAGE_OPERATIONS.ENLARGE,
    icon: '/static/images/upscale_icon.png',
    text: computed(() => t('upscale')),
    className: 'upscale-btn'
  }
]);

// 3. 计算属性区域
const favoriteIcon = computed(() => {
  return isFavorited.value ? '/static/mobile_images/hearted_icon.png' : '/static/mobile_images/heart_icon.png';
});


const seedDisplayValue = computed(() => {
  return imageData.value.seed || '';
});

// 4. 点击事件区域
// 防抖的接口同步函数
const syncFavoriteToServer = debounce(async (targetState, mediaId) => {
  try {
    const response = await ApiGeneration.toggleFavorite(mediaId);
    // 根据服务器返回确认状态
    isFavorited.value = response.data.is_favorited;
  } catch (error) {
    // 如果接口失败，回滚到目标状态
    isFavorited.value = targetState;
    console.error('Toggle favorite failed:', error);
    showMessageError(t('operationFailed'));
  }
}, 300);

// 立即执行的点击处理函数
const toggleFavorite = () => {
  // 立即切换UI状态，用户马上看到变化
  isFavorited.value = !isFavorited.value;
  
  // 调用防抖的接口同步函数
  syncFavoriteToServer(isFavorited.value, imageData.value.media_id);
};

// 统一的按钮点击处理
const handleButtonClick = (actionKey) => {
  // 根据操作类型显示不同的确认弹窗
  handleMobileMediaAction(
    { type: actionKey }, // 操作类型
    imageData.value,     // 媒体数据
    {
      directClose: true,  // 使用直接关闭模式
      onSuccess: () => {
        console.log('onSuccess', actionKey);
        // 确认后执行原有的操作逻辑，但跳过下载操作（下载由handler内部完成）
        switch (actionKey) {
          case IMAGE_OPERATIONS.DOWNLOAD:
            // 下载操作已在handleMobileMediaAction内部完成，这里不需要再执行
            console.log('Download completed by handler');
            break;
          case IMAGE_OPERATIONS.EDIT:
            handleEdit();
            break;
          case IMAGE_OPERATIONS.ENHANCE:
            handleEnhance();
            break;
          case IMAGE_OPERATIONS.TO_VIDEO:
            handleToVideo();
            break;
          case IMAGE_OPERATIONS.ENLARGE:
            handleUpscale();
            break;
        }
      },
      onError: (type, error) => {
        console.error('Operation error:', type, error);
        showMessageError(t('operationFailed'));
      },
      onCancel: () => {
        console.log('Operation cancelled');
      }
    }
  ).catch(error => {
    if (!error.cancelled) {
      console.error('Dialog error:', error);
    }
  });
};

const handleRetry = () => {
  // 重新加载页面
  window.location.reload();
};

// 5. 自定义事件区域
const handleTaskCompleted = (data) => {
  if (data.taskId === currentTaskId.value) {
    const mediaList = data.result.media_list;
    if (mediaList && mediaList.length > 0) {
      imageData.value = {
        url: mediaList[0].file_url,
        seed: mediaList[0]?.seed || '',
        media_id: mediaList[0]?.id || ''
      };
      currentState.value = 'success';
    }
  }
};

const handleTaskFailed = (data) => {
  if (data.taskId === currentTaskId.value) {
    errorMessage.value = data.error || t('generateFailed');
    currentState.value = 'error';
  }
};

const handleTaskStatusUpdate = (data) => {
  if (data.taskId === currentTaskId.value) {
    // 更新进度信息（如果需要显示进度）
    console.log(`Task progress: ${data.res?.progress || 0}%`);
  }
};

// 6. 业务逻辑区域
const handleDownload = async () => {
  if (!imageData.value.url) {
    showMessageWarning(t('noImageToDownload'));
    return;
  }
  
  try {
    const result = await downloadImage(imageData.value.url);
    if (result.success) {
      console.log(`Download started: ${result.message}, method: ${result.method}`);
    }
  } catch (error) {
    console.error('Download failed:', error);
    showMessageError(t('downloadFailed') || 'Download failed');
  }
};

const handleEdit = () => {
  // 先设置Pinia中图片编辑页面的数据
  mediaStore.setGenerationResult(IMAGE_OPERATIONS.EDIT, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    dimensions: null // 可以根据实际情况设置
  });
  
  // 跳转到图片编辑页面
  routerTo(ROUTER_PATHS.IMAGE_EDITOR, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    source: 'mobile-text-to-image'
  });
};

const handleEnhance = () => {
  // 先设置Pinia中图片增强页面的数据
  mediaStore.setGenerationResult(IMAGE_OPERATIONS.ENHANCE, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    dimensions: null // 可以根据实际情况设置
  });
  
  // 跳转到图片增强页面
  routerTo(ROUTER_PATHS.IMAGE_ENHANCEMENT, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    source: 'mobile-text-to-image'
  });
};

const handleToVideo = () => {
  // 先设置Pinia中图片转视频页面的数据
  mediaStore.setGenerationResult(IMAGE_OPERATIONS.TO_VIDEO, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    dimensions: null // 可以根据实际情况设置
  });
  
  // 跳转到图片转视频页面
  routerTo(ROUTER_PATHS.TEXT_TO_IMAGE_TO_VIDEO, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    source: 'mobile-text-to-image'
  });
};

const handleUpscale = () => {
  // 先设置Pinia中图片放大页面的数据
  mediaStore.setGenerationResult(IMAGE_OPERATIONS.ENLARGE, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    dimensions: null // 可以根据实际情况设置
  });
  
  // 跳转到图片放大页面
  routerTo(ROUTER_PATHS.IMAGE_UPSCALER, {
    imageUrl: imageData.value.url,
    seed: imageData.value.seed,
    source: 'mobile-text-to-image'
  });
};

// 7. 初始化方法区域
const initializeComponent = () => {
  // 从路由参数获取taskId
  currentTaskId.value = route.params.taskId;
  
  if (!currentTaskId.value) {
    errorMessage.value = t('invalidTaskId');
    currentState.value = 'error';
    return;
  }
  
  // 检查本地轮询任务队列，如果没有该id则加入该id
  const existingTask = MediaTaskPolling.getTask(currentTaskId.value);
  if (!existingTask) {
    console.log(`Adding image task ${currentTaskId.value} to polling queue`);
    MediaTaskPolling.addTask(currentTaskId.value, TaskType.IMAGE);
  } else {
    console.log(`Image task ${currentTaskId.value} already exists in polling queue`);
  }
  
  // 设置路由meta信息
  const meta = router.currentRoute.value.meta;
  meta.taskId = currentTaskId.value;
  meta.type = TaskType.IMAGE;
  
  // 设置初始状态为加载中
  currentState.value = 'loading';
};

const bindEventListeners = () => {
  // 监听轮询事件
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
};

// 8. 周期函数区域
onMounted(() => {
  initializeComponent();
  bindEventListeners();
});

onBeforeUnmount(() => {
  clearMediaTaskEventListeners();
});

onUnmounted(() => {
  // 清除路由meta中的taskId
  const meta = router?.currentRoute?.value?.meta;
  if (meta) {
    meta.taskId = null;
    meta.type = null;
  }
});
</script>

